using System;using System.Linq;using System.Drawing;using System.Drawing.Drawing2D;using System.Collections.Generic;using System.Windows.Forms;
namespace GearLab {
 public sealed class CADSketchCanvas:Control {
  public CADSketch Sketch=new CADSketch();public Dictionary<string,double> Parameters=new Dictionary<string,double>();public string Tool="select";public readonly List<string> Selected=new List<string>();public bool Snap=true;public double Step=1;public event Action Changed,SelectionChanged;public event Action<string> Status;double scale=7;PointF pan;Point previous;bool panning,drawing;double[] first,last;readonly List<double[]> chain=new List<double[]>();string dragged;int dragPoint=-1;readonly Dictionary<string,int> pointSelection=new Dictionary<string,int>();
  public CADSketchCanvas(){DoubleBuffered=true;BackColor=Color.FromArgb(250,252,254);Dock=DockStyle.Fill;SetStyle(ControlStyles.Selectable,true);TabStop=true;Font=new Font("Segoe UI",9);}
  public void SetTool(string tool){Tool=tool;chain.Clear();drawing=false;dragged=null;Cursor=tool=="select"?Cursors.Arrow:Cursors.Cross;Invalidate();}
  public int PointIndex(string id){int i;return pointSelection.TryGetValue(id,out i)?i:0;}
  public List<double[]> SampleEntity(CADEntity entity){return Outline(entity);}
  double Num(string s){try{return CADExpression.Evaluate(s,Parameters);}catch{return 0;}}
  PointF Screen(double[] p){return new PointF((float)(Width/2+pan.X+p[0]*scale),(float)(Height/2+pan.Y-p[1]*scale));}
  double[] World(Point p){double x=(p.X-Width/2-pan.X)/scale,y=(Height/2+pan.Y-p.Y)/scale;if(Snap){x=Math.Round(x/Step)*Step;y=Math.Round(y/Step)*Step;}return new[]{x,y};}
  static double Dist(double[] a,double[] b){return Math.Sqrt((a[0]-b[0])*(a[0]-b[0])+(a[1]-b[1])*(a[1]-b[1]));}
  List<double[]> Outline(CADEntity e){var p=e.Points;if(p.Count==0)return new List<double[]>();double x=p[0][0],y=p[0][1],r=Num(e.Radius),w=Num(e.Width),h=Num(e.Height);switch(e.Kind){case "circle":return Enumerable.Range(0,97).Select(i=>new[]{x+r*Math.Cos(Engine.Tau*i/96),y+r*Math.Sin(Engine.Tau*i/96)}).ToList();case "rectangle":return new List<double[]>{new[]{x,y},new[]{x+w,y},new[]{x+w,y+h},new[]{x,y+h},new[]{x,y}};case "polygon":int n=Math.Max(3,Math.Min(128,(int)Num(e.Count)));return Enumerable.Range(0,n+1).Select(i=>new[]{x+r*Math.Cos(Engine.Tau*i/n),y+r*Math.Sin(Engine.Tau*i/n)}).ToList();case "slot":var result=new List<double[]>();double span=w-2*r;for(int i=0;i<=24;i++){double a=-Math.PI/2+Math.PI*i/24;result.Add(new[]{x+span+r*Math.Cos(a),y+r*Math.Sin(a)});}for(int i=0;i<=24;i++){double a=Math.PI/2+Math.PI*i/24;result.Add(new[]{x+r*Math.Cos(a),y+r*Math.Sin(a)});}result.Add(result[0]);return result;case "arc":if(p.Count==3){double ax=p[0][0],ay=p[0][1],bx=p[1][0],by=p[1][1],cx=p[2][0],cy=p[2][1],d=2*(ax*(by-cy)+bx*(cy-ay)+cx*(ay-by));if(Math.Abs(d)<1e-8)return p;double ux=((ax*ax+ay*ay)*(by-cy)+(bx*bx+by*by)*(cy-ay)+(cx*cx+cy*cy)*(ay-by))/d,uy=((ax*ax+ay*ay)*(cx-bx)+(bx*bx+by*by)*(ax-cx)+(cx*cx+cy*cy)*(bx-ax))/d;double a0=Math.Atan2(ay-uy,ax-ux),am=Math.Atan2(by-uy,bx-ux),a1=Math.Atan2(cy-uy,cx-ux);Func<double,double> positive=a=>(a+Engine.Tau*2)%Engine.Tau;double sweep=positive(a1-a0);if(positive(am-a0)>sweep)sweep-=Engine.Tau;r=Math.Sqrt((ax-ux)*(ax-ux)+(ay-uy)*(ay-uy));return Enumerable.Range(0,65).Select(i=>new[]{ux+r*Math.Cos(a0+sweep*i/64),uy+r*Math.Sin(a0+sweep*i/64)}).ToList();}break;}var points=p.ToList();if(e.Closed&&points.Count>2)points.Add(points[0]);return points;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;double spacing=Step;while(spacing*scale<15)spacing*=5;while(spacing*scale>100)spacing/=2;var origin=Screen(new double[2]);using(var grid=new Pen(Color.FromArgb(226,233,240)))using(var xpen=new Pen(Color.FromArgb(205,104,104),1.3f))using(var ypen=new Pen(Color.FromArgb(87,160,117),1.3f)){double px=spacing*scale;for(double x=origin.X%px;x<Width;x+=px)g.DrawLine(grid,(float)x,0,(float)x,Height);for(double y=origin.Y%px;y<Height;y+=px)g.DrawLine(grid,0,(float)y,Width,(float)y);g.DrawLine(xpen,0,origin.Y,Width,origin.Y);g.DrawLine(ypen,origin.X,0,origin.X,Height);g.DrawString("X",Font,Brushes.Firebrick,Width-24,origin.Y+4);g.DrawString("Y",Font,Brushes.SeaGreen,origin.X+5,8);}
   foreach(var entity in Sketch.Entities)DrawEntity(g,entity,Selected.Contains(entity.Id));if(drawing&&first!=null&&last!=null){var temp=new CADEntity{Kind=Tool,Points=new List<double[]>{first},Width=Engine.N(last[0]-first[0]),Height=Engine.N(last[1]-first[1]),Radius=Engine.N(Dist(first,last))};if(Tool=="line")temp.Points.Add(last);DrawEntity(g,temp,true);}if(chain.Count>0){var points=chain.Concat(last==null?new double[0][]:new[]{last}).Select(Screen).ToArray();using(var pen=new Pen(Color.DarkOrange,2)){if(points.Length>1)g.DrawLines(pen,points);}}g.DrawString("Плоскость "+Sketch.Plane+" · "+ToolName()+" · Enter — завершить цепочку · Esc — отменить инструмент · колесо — масштаб · СКМ — сдвиг",Font,Brushes.SlateGray,12,Height-28);
  }
  string ToolName(){return Tool=="select"?"Выбор / перемещение точек":CADTools.EntityName(Tool);}
  void DrawEntity(Graphics g,CADEntity e,bool selected){var path=Outline(e).Select(Screen).ToArray();if(path.Length<2)return;bool closed=e.Closed||new[]{"circle","rectangle","polygon","slot"}.Contains(e.Kind);if(closed&&!e.Construction&&path.Length>2)using(var brush=new SolidBrush(Color.FromArgb(28,70,137,212)))g.FillPolygon(brush,path);using(var pen=new Pen(selected?Color.FromArgb(232,132,24):e.Construction?Color.FromArgb(153,135,114):Color.FromArgb(42,111,182),selected?2.6f:1.7f)){if(e.Construction)pen.DashStyle=DashStyle.Dash;if(e.Kind=="spline"&&path.Length>2)g.DrawCurve(pen,path);else g.DrawLines(pen,path);}if(selected){foreach(var p in e.Points){var q=Screen(p);g.FillRectangle(Brushes.White,q.X-4,q.Y-4,8,8);g.DrawRectangle(Pens.DarkOrange,q.X-4,q.Y-4,8,8);}if(e.Kind=="circle"){var c=Screen(e.Points[0]);g.DrawString("R = "+e.Radius,Font,Brushes.DarkOrange,c.X+8,c.Y-22);var h=Screen(new[]{e.Points[0][0]+Num(e.Radius),e.Points[0][1]});g.FillEllipse(Brushes.DarkOrange,h.X-4,h.Y-4,8,8);}if(e.Kind=="rectangle")g.DrawString(e.Width+" × "+e.Height+" мм",Font,Brushes.DarkOrange,path[0].X+5,path[0].Y+8);}}
  static double SegmentDistance(PointF p,PointF a,PointF b){double dx=b.X-a.X,dy=b.Y-a.Y,t=Math.Max(0,Math.Min(1,((p.X-a.X)*dx+(p.Y-a.Y)*dy)/Math.Max(1e-10,dx*dx+dy*dy)));return Math.Sqrt(Math.Pow(p.X-a.X-t*dx,2)+Math.Pow(p.Y-a.Y-t*dy,2));}
  CADEntity Hit(Point point){double best=9;CADEntity hit=null;foreach(var e in Sketch.Entities){var p=Outline(e).Select(Screen).ToArray();for(int i=1;i<p.Length;i++){double d=SegmentDistance(point,p[i-1],p[i]);if(d<best){best=d;hit=e;}}}return hit;}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Focus();previous=e.Location;last=World(e.Location);if(e.Button==MouseButtons.Middle){panning=true;Capture=true;return;}if(e.Button!=MouseButtons.Left)return;if(Tool=="select"){foreach(string id in Selected){var en=Sketch.Entities.FirstOrDefault(x=>x.Id==id);if(en==null)continue;for(int i=0;i<en.Points.Count;i++)if(Dist(ScreenArray(en.Points[i]),new[]{(double)e.X,(double)e.Y})<9){dragged=id;dragPoint=i;Capture=true;return;}if(en.Kind=="circle"&&Dist(ScreenArray(new[]{en.Points[0][0]+Num(en.Radius),en.Points[0][1]}),new[]{(double)e.X,(double)e.Y})<9){dragged=id;dragPoint=-2;Capture=true;return;}}var hit=Hit(e.Location);if((ModifierKeys&Keys.Control)==0)Selected.Clear();if(hit!=null){if(Selected.Contains(hit.Id))Selected.Remove(hit.Id);else Selected.Add(hit.Id);pointSelection[hit.Id]=Enumerable.Range(0,hit.Points.Count).OrderBy(i=>Dist(hit.Points[i],last)).FirstOrDefault();}if(SelectionChanged!=null)SelectionChanged();Invalidate();return;}if(Tool=="arc"||Tool=="polyline"||Tool=="spline"){if(e.Clicks>1){FinishChain();return;}chain.Add(last);if(Tool=="arc"&&chain.Count==3)FinishChain();Invalidate();return;}first=last;drawing=true;Capture=true;}
  double[] ScreenArray(double[] p){var q=Screen(p);return new[]{(double)q.X,(double)q.Y};}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);last=World(e.Location);if(Status!=null)Status("X "+Engine.F(last[0])+" · Y "+Engine.F(last[1])+" мм");if(panning){pan.X+=e.X-previous.X;pan.Y+=e.Y-previous.Y;previous=e.Location;Invalidate();return;}if(dragged!=null){var en=Sketch.Entities.First(x=>x.Id==dragged);if(dragPoint>=0)en.Points[dragPoint]=last;else en.Radius=Engine.N(Dist(en.Points[0],last));if(Changed!=null)Changed();}if(drawing||chain.Count>0||dragged!=null)Invalidate();}
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);Capture=false;if(panning){panning=false;return;}if(dragged!=null){dragged=null;return;}if(!drawing||first==null)return;drawing=false;var end=World(e.Location);if(Dist(first,end)<.1)return;var entity=new CADEntity{Kind=Tool,Points=new List<double[]>{first},Width=Engine.N(end[0]-first[0]),Height=Engine.N(end[1]-first[1]),Radius=Engine.N(Dist(first,end))};if(Tool=="line")entity.Points.Add(end);if(Tool=="rectangle"){entity.Points[0]=new[]{Math.Min(first[0],end[0]),Math.Min(first[1],end[1])};entity.Width=Engine.N(Math.Abs(end[0]-first[0]));entity.Height=Engine.N(Math.Abs(end[1]-first[1]));}if(Tool=="slot"){double r=Math.Max(1,Math.Abs(end[1]-first[1]));entity.Radius=Engine.N(r);entity.Width=Engine.N(Math.Max(r*2,Math.Abs(end[0]-first[0])));}Add(entity);}
  void Add(CADEntity e){Sketch.Entities.Add(e);Selected.Clear();Selected.Add(e.Id);if(Changed!=null)Changed();if(SelectionChanged!=null)SelectionChanged();Invalidate();}
  public void FinishChain(){int required=Tool=="arc"||Tool=="spline"?3:2;if(chain.Count<required){chain.Clear();Invalidate();return;}var e=new CADEntity{Kind=Tool,Points=chain.Select(p=>p.ToArray()).ToList()};if(Tool=="polyline"&&e.Points.Count>3&&Dist(e.Points[0],e.Points.Last())<=Math.Max(Step,.1)){e.Closed=true;e.Points.RemoveAt(e.Points.Count-1);}chain.Clear();Add(e);}
  public void DeleteSelection(){var ids=new HashSet<string>(Selected);Sketch.Entities.RemoveAll(e=>ids.Contains(e.Id));Sketch.Constraints.RemoveAll(c=>ids.Contains(c.A)||ids.Contains(c.B));Selected.Clear();if(Changed!=null)Changed();if(SelectionChanged!=null)SelectionChanged();Invalidate();}
  public void Fit(){var points=Sketch.Entities.SelectMany(Outline).ToList();if(points.Count==0)return;double minX=points.Min(p=>p[0]),maxX=points.Max(p=>p[0]),minY=points.Min(p=>p[1]),maxY=points.Max(p=>p[1]);scale=Math.Max(.05,Math.Min((Width-100)/Math.Max(1,maxX-minX),(Height-100)/Math.Max(1,maxY-minY)));pan=new PointF((float)(-(minX+maxX)*scale/2),(float)((minY+maxY)*scale/2));Invalidate();}
  protected override void OnMouseWheel(MouseEventArgs e){var before=World(e.Location);scale=Math.Max(.05,Math.Min(100,scale*Math.Exp(e.Delta*.0014)));pan=new PointF((float)(e.X-Width/2-before[0]*scale),(float)(e.Y-Height/2+before[1]*scale));Invalidate();base.OnMouseWheel(e);}
  protected override bool IsInputKey(Keys keyData){return keyData==Keys.Enter||keyData==Keys.Escape||base.IsInputKey(keyData);}protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Enter){FinishChain();e.Handled=true;}else if(e.KeyCode==Keys.Escape){SetTool("select");e.Handled=true;}else if(e.KeyCode==Keys.Delete){DeleteSelection();e.Handled=true;}base.OnKeyDown(e);}
 }
}
